// Helper functions for data table styling and logic
func getDataTableData(props DataTableProps) string {
	pageSize := 10
	if props.PageSize > 0 {
		pageSize = props.PageSize
	}

	currentPage := 1
	if props.CurrentPage > 0 {
		currentPage = props.CurrentPage
	}

	// Use extracted hook system
	service := props.ServiceContext.Service
	if service == "" {
		service = "console" // Default fallback
	}

	return `window.create` + strings.Title(service) + `DataTable({
		rows: ` + getRowsJSON(props.Rows) + `,
		pageSize: ` + strconv.Itoa(pageSize) + `,
		currentPage: ` + strconv.Itoa(currentPage) + `,
		searchColumns: ` + getSearchColumnsJSON(props.Columns) + `,
		bulkActions: ` + getBulkActionsJSON(props.BulkActions) + `,
		permissions: ` + getPermissionsJSON(props.ServiceContext.Permissions) + `,
		serviceContext: '` + service + `'
	})`
}

// Helper functions for JSON serialization
func getSearchColumnsJSON(columns []DataTableColumn) string {
	var keys []string
	for _, col := range columns {
		keys = append(keys, `"`+col.Key+`"`)
	}
	return `[` + strings.Join(keys, ", ") + `]`
}

func getBulkActionsJSON(actions []BulkActionProps) string {
	if len(actions) == 0 {
		return "[]"
	}

	var jsonActions []string
	for _, action := range actions {
		jsonAction := `{
			"id": "` + action.ID + `",
			"text": "` + action.Text + `",
			"icon": "` + action.Icon + `",
			"variant": "` + action.Variant + `",
			"permission": "` + action.Permission + `",
			"confirm": ` + strconv.FormatBool(action.Confirm) + `,
			"confirmText": "` + action.ConfirmText + `",
			"endpoint": "` + action.Endpoint + `",
			"method": "` + action.Method + `"
		}`
		jsonActions = append(jsonActions, jsonAction)
	}
	return `[` + strings.Join(jsonActions, ", ") + `]`
}

func getPermissionsJSON(permissions []string) string {
	if len(permissions) == 0 {
		return "[]"
	}

	var quotedPerms []string
	for _, perm := range permissions {
		quotedPerms = append(quotedPerms, `"`+perm+`"`)
	}
	return `[` + strings.Join(quotedPerms, ", ") + `]`
}

