func getCellContentExpression(column DataTableColumn) string {
	switch column.Type {
	case "badge":
		return "getBadgeContent(row.data['" + column.Key + "'])"
	case "currency":
		return "formatCurrency(row.data['" + column.Key + "'])"
	case "date":
		return "formatDate(row.data['" + column.Key + "'])"
	default:
		return "row.data['" + column.Key + "']"
	}
}

func getBulkActionHandler(action BulkActionProps) string {
	if action.Confirm {
		confirmText := action.ConfirmText
		if confirmText == "" {
			confirmText = "Are you sure you want to " + strings.ToLower(action.Text) + " the selected items?"
		}
		return "handleBulkActionWithConfirm('" + action.ID + "', '" + confirmText + "')"
	}
	return "handleBulkAction('" + action.ID + "')"
}

func hasRowActions(rows []DataTableRow) bool {
	for _, row := range rows {
		if len(row.Actions) > 0 {
			return true
		}
	}
	return false
}

func getTotalColumns(props DataTableProps) int {
	total := len(props.Columns)
	if props.Selectable {
		total++
	}
	if hasRowActions(props.Rows) {
		total++
	}
	return total
}

