// hasPermissionForBulkAction checks if user has permission for a bulk action
func hasPermissionForBulkAction(ctx context.Context, permission string, serviceContext ServiceContextProps) bool {
	if permission == "" {
		return true // No permission required
	}

	// Parse permission string (format: "resource:action" or just "action")
	parts := strings.Split(permission, ":")
	if len(parts) == 1 {
		// Simple action check (e.g., "admin", "manage")
		return checkServicePermission(ctx, "navigation", parts[0], serviceContext)
	} else if len(parts) == 2 {
		// Resource:action format (e.g., "users:delete", "tenants:suspend")
		return checkServicePermission(ctx, parts[0], parts[1], serviceContext)
	}

	return false
}

